const categoryPath=model=>modelClassification(model).join(' / ');
const mountKindName=kind=>mountKinds.find(item=>item.id===kind)?.name||'挂载';
const mountItemName=kind=>mountKinds.find(item=>item.id===kind)?.itemName||'实体';
const mountOptionLabel=kind=>kind.id==='ammo'?'直接挂载武器':`${kind.name}（挂载${kind.itemName}）`;
const mountQtyButton=(parentId,group,delta)=>`<button class="icon-button" data-act="mount-qty" data-delta="${delta}" data-mount-parent="${parentId}" data-mount-kind="${group.kind}" data-mount-model="${esc(group.model.id)}" title="${delta<0?'减少 1 个':'增加 1 个'}" aria-label="${delta<0?'减少':'增加'} ${esc(group.model.mxmc)} 数量">${delta<0?'−':'＋'}</button>`;
const weaponModels=(plan,parentId)=>{const groups=new Map();for(const entity of mountedWeaponEntities(plan,parentId)){const entry=groups.get(entity.model.id)||{model:entity.model,count:0};entry.count++;groups.set(entity.model.id,entry);}return [...groups.values()];};
const PAGE_SIZE=50;
const searchMatch=(query,...values)=>!query.trim()||values.some(value=>String(value??'').toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
const paginate=(items,page,size=PAGE_SIZE)=>{const pages=Math.max(1,Math.ceil(items.length/size)),current=Math.min(Math.max(1,page),pages),start=(current-1)*size;return {items:items.slice(start,start+size),page:current,pages,total:items.length,start};};
const pager=(scope,page,pages,total)=>`<div class="catalog-pager"><span>共 ${total} 条 · 第 ${page} / ${pages} 页</span><div class="row"><button class="button small" data-act="page" data-scope="${scope}" data-value="${page-1}" ${page<=1?'disabled':''}>上一页</button><button class="button small" data-act="page" data-scope="${scope}" data-value="${page+1}" ${page>=pages?'disabled':''}>下一页</button></div></div>`;
const modelCard=m=>`<div class="panel model-card"><div class="row between">${chip(esc(m.FirstCfn||'未分类'),'purple')}<span class="mono muted">型号 ${esc(m.id)}</span></div><div class="model-visual">${icon('plane')}</div><h3>${esc(m.mxmc)}</h3><span class="mono muted" style="font-size:10px">${esc(m.mxnm)}</span><p>${esc(m.description||'可用于地图实体或挂载实体。')}</p><div class="model-meta"><span>${esc(modelClassification(m).slice(1).join(' / '))}</span><button class="text-button" data-act="model-detail" data-id="${esc(m.id)}" style="font-size:10px">配置 ${icon('arrow')}</button></div></div>`;
function modelCatalog(){
  let list=db.models;
  for(const [index,[key]] of classificationFields.entries())if(ui.modelCategories[index])list=list.filter(model=>(model[key]||'未分类')===ui.modelCategories[index]);
  list=list.filter(model=>searchMatch(ui.modelQuery,model.mxmc,...modelClassification(model),model.description));
  const localPage=paginate(list,ui.modelPage),key=modelCatalogKey(),remote=remoteModelPage?.key===key?remoteModelPage:null,page=remote?{items:remote.items,page:remote.page,pages:remote.pages,total:remote.total}:localPage;if(!remote)queueMicrotask(()=>loadModelCatalogPage(key));
  const filters=classificationFields.map(([key,label],index)=>{const values=[...new Set(db.models.map(model=>model[key]||'未分类'))].sort((a,b)=>a.localeCompare(b,'zh-CN'));return `<label class="compact-field"><span>${label}</span><select data-ui-filter="model-category" data-index="${index}" aria-label="筛选${label}"><option value="">全部</option>${values.map(value=>`<option value="${esc(value)}" ${ui.modelCategories[index]===value?'selected':''}>${esc(value)}</option>`).join('')}</select></label>`;}).join('');
  const toolbar=`<div class="catalog-toolbar"><div class="searchbox">${icon('search')}<input id="model-search" type="search" placeholder="搜索装备名称或分类…" aria-label="搜索装备目录" value="${esc(ui.modelQuery)}"></div>${filters}<div class="segmented"><button data-act="catalog-view" data-value="table" class="${ui.modelView==='table'?'active':''}">表格</button><button data-act="catalog-view" data-value="cards" class="${ui.modelView==='cards'?'active':''}">卡片</button></div></div>`;
  const table=`<div class="panel"><div class="table-scroll"><table><thead><tr><th>装备名称</th><th>一级分类</th><th>二级分类</th><th>三级分类</th><th>四级分类</th><th>说明</th><th>操作</th></tr></thead><tbody>${page.items.map(model=>`<tr><td><b>${esc(model.mxmc)}</b></td>${classificationFields.map(([key])=>`<td>${esc(model[key]||'未分类')}</td>`).join('')}<td class="cell-description">${esc(model.description||'—')}</td><td>${button('查看','model-detail','','small',`data-id="${esc(model.id)}"`)}</td></tr>`).join('')}</tbody></table></div>${pager('models',page.page,page.pages,page.total)}</div>`;
  const cards=`<div class="library-grid">${page.items.map(modelCard).join('')}</div>${pager('models',page.page,page.pages,page.total)}`;
  return `${toolbar}${page.total?(ui.modelView==='cards'?cards:table):empty('没有匹配的装备型号','调整搜索或分类条件。')}<button class="panel model-card add-model-card compact-add" data-act="add-model">${icon('plus')}<h3>添加一个型号</h3></button>`;
}
