function infoTab(p){return `<div class="editor-info"><div class="form-section"><h3>方案基本信息</h3><div class="form-grid">${field('方案名称 <span class="required">*</span>',`<input data-plan="name" aria-label="方案名称" maxlength="60" value="${esc(p.name)}">`,'便于区分用途，生成标题会自动附加唯一编号。','full')}${field('方案说明',`<textarea rows="3" data-plan="description" aria-label="方案说明" placeholder="记录这次仿真的目的…">${esc(p.description)}</textarea>`,'','full')}${field('仿真开始时间',`<input type="datetime-local" step="1" data-plan="start" aria-label="仿真开始时间" value="${p.start.replace(' ','T')}">`)}${field('仿真结束时间',`<input type="datetime-local" step="1" data-plan="end" aria-label="仿真结束时间" value="${p.end.replace(' ','T')}">`)}</div></div>${note(`当前仿真时长 <b>${Number.isFinite(duration(p))?duration(p):'—'} 秒</b>。行动时间从仿真开始的第 0 秒计算。`)}<div style="margin-top:24px">${button('前往想定编辑','editor-tab','arrow','primary','data-value="map"')}</div></div>`;}
