    const children=mountedEntities(p,entity.id),matches=searchMatch(ui.entityQuery,entity.name,entity.model.mxmc,...modelClassification(entity.model))||children.some(child=>searchMatch(ui.entityQuery,child.name,child.model.mxmc,mountKindName(child.mountKind)));
