function entityTable(p,roots){return `<div class="entity-table-stage"><div class="table-scroll"><table><thead><tr><th></th><th>实体名称</th><th>阵营</th><th>装备</th><th>分类</th><th>坐标</th><th>挂载</th><th>行动</th></tr></thead><tbody>${roots.map(entity=>`<tr class="${entity.id===ui.entity?'selected-row':''}"><td><input type="checkbox" data-entity-select="${entity.id}" aria-label="选择实体 ${esc(entity.name)}" ${ui.entitySelected.has(entity.id)?'checked':''}></td><td><button class="text-button" data-act="select-entity" data-id="${entity.id}">${esc(entity.name)}</button></td><td><i class="side-dot ${entity.side==='Red'?'red':'blue'}"></i> ${entity.side==='Red'?'红方':'蓝方'}</td><td>${esc(entity.model.mxmc)}</td><td>${esc(categoryPath(entity.model))}</td><td class="mono">${entity.lon.toFixed(4)}, ${entity.lat.toFixed(4)}, ${entity.height}</td><td>${mountedEntities(p,entity.id).length}</td><td>${p.actions.filter(action=>action.executor===entity.id).length}</td></tr>`).join('')}</tbody></table></div></div>`;}
