  let actions=p.actions.filter(action=>{const executor=rootById.get(action.executor),invalid=ui.actionStatus==='all'?false:actionHasError(action,p),start=ui.actionStart===''?null:Number(ui.actionStart),end=ui.actionEnd===''?null:Number(ui.actionEnd);return searchMatch(ui.actionQuery,action.name,action.code,executor?.name)&&(ui.actionSide==='all'||executor?.side===ui.actionSide)&&(ui.actionType==='all'||action.code===ui.actionType)&&(ui.actionStatus==='all'||(ui.actionStatus==='error')===invalid)&&(start==null||action.end>=start)&&(end==null||action.start<=end);});
  const order=ui.actionSort==='time-desc'?(a,b)=>b.start-a.start:ui.actionSort==='name'?(a,b)=>a.name.localeCompare(b.name,'zh-CN'):(a,b)=>a.start-b.start;
